def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or seen[r][c]:
                continue
            comp = []
            stack = [(r, c)]
            seen[r][c] = True
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 0 and not seen[ny][nx]):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            components.append(comp)

    if not components:
        return [row[:] for row in grid]

    smallest = min(map(len, components))
    largest = max(map(len, components))
    out = [row[:] for row in grid]

    for comp in components:
        if len(comp) == smallest:
            for r, c in comp:
                out[r][c] = 7
        if len(comp) == largest:
            for r, c in comp:
                out[r][c] = 8

    return out
